// Friday 1AM reset — clears all message sent records for the week
// Returns true if we are past Friday 1AM and the reset hasn't been done yet this week
function checkFridayReset() {
  var now = new Date();
  var day = now.getDay(); // 0=Sun,5=Fri
  var hour = now.getHours();
  // Friday=5, after 1AM
  if (day === 5 && hour >= 1) {
    var resetKey = "jg_friday_reset_" + now.getFullYear() + "_W" + getWeekNumber(now);
    if (!localStorage.getItem(resetKey)) {
      // Clear all message logs
      var keys = Object.keys(localStorage);
      keys.forEach(function (k) {
        if (k.startsWith("msg_")) localStorage.removeItem(k);
      });
      localStorage.setItem(resetKey, "done");
      console.log("Friday reset done");
    }
  }
}
function getWeekNumber(d) {
  var onejan = new Date(d.getFullYear(), 0, 1);
  return Math.ceil(((d - onejan) / 86400000 + onejan.getDay() + 1) / 7);
}

// SMS link helper
function toSMS(num, msg) {
  if (!num || String(num).trim() === "" || String(num).trim() === "?") return null;
  var d = String(num).replace(/\D/g, "");
  if (d.length < 9) return null;
  var i = d.startsWith("0") ? "+27" + d.slice(1) : d.startsWith("27") ? "+" + d : "+27" + d;
  // Use sms: format - works on both iOS and Android
  // iOS needs & separator, Android needs ?
  var isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent);
  if (!msg) return "sms:" + i;
  var sep = isIOS ? "&" : "?";
  return "sms:" + i + sep + "body=" + encodeURIComponent(msg);
}

